pub fn language_for_glob(base: &str) -> Option<&'static Language> {
    let lower = base.to_ascii_lowercase();
    for (pattern, lang) in GLOBS {
        if glob_match(pattern, &lower) {
            return Some(lang);
        }
    }
    None
}

