/// Matches a basename against a simple glob (`*` and `?` wildcards).
fn glob_match(pattern: &str, name: &str) -> bool {
    fn rec(p: &[u8], n: &[u8]) -> bool {
        if p.is_empty() {
            return n.is_empty();
        }
        match p[0] {
            b'*' => rec(&p[1..], n) || (!n.is_empty() && rec(p, &n[1..])),
            b'?' => !n.is_empty() && rec(&p[1..], &n[1..]),
            c => !n.is_empty() && n[0] == c && rec(&p[1..], &n[1..]),
        }
    }
    rec(pattern.as_bytes(), name.as_bytes())
}

pub fn language_server(name: &str) -> Option<(&'static str, &'static [&'static str])> {
    LANGUAGE_SERVERS
        .iter()
        .find(|(n, _, _)| *n == name)
        .map(|(_, cmd, args)| (*cmd, *args))
}
